import { both, phrase, replies, type PhoneLessonContract } from './contracts';

type Entry = {
  name: string; role: string; gender: 'male' | 'female'; user: string;
  call: 'incoming' | 'outgoing'; situation: string;
  goals: [string, string, string]; facts: string[]; ask: string[];
  forbidden: string[]; greeting: [string, string, string];
  reply: [string, string, string]; femaleReply?: [string, string, string]; turns?: 3 | 4;
};

// Each entry supplies its own phone situation, information ownership and outcome.
// Both profiles share only phrases without gendered references to the student.
function contract(e: Entry): PhoneLessonContract {
  return {
    callerName: e.name, callerNameRu: e.name, callerRole: e.role,
    callerGender: e.gender, userRole: e.user, callType: e.call,
    situationSummary: e.situation,
    callerObjective: `В роли «${e.role}» помочь разыграть ситуацию: ${e.situation}`,
    studentObjective: e.goals.join('; '), goals: e.goals,
    completionCondition: `По смыслу выполнены все задачи: ${e.goals.join('; ')}. Ученик может использовать другие слова. Вежливый отказ допустим там, где предусмотрен целью; непонимание или один короткий ответ не доказывают выполнение остальных задач.`,
    facts: e.facts, studentDetails: e.ask,
    forbiddenActions: [
      'Не произносить ответы и просьбы от лица ученика; не задавать ученику вопросы о фактах, которыми владеет персонаж.',
      'Не повторять уже полученные сведения; предложение не считать согласием ученика.',
      ...e.forbidden,
    ],
    memoryScope: 'general', targetTurns: e.turns ?? 4,
    greeting: both(phrase(...e.greeting)),
    studentReplies: e.femaleReply
      ? { male: [phrase(...e.reply)], female: [phrase(...e.femaleReply)] }
      : replies(phrase(...e.reply)),
  };
}

